SELECT
  count(*) totcnt
FROM
  ttokssaemdb.vocamemo


    AND memberid = #{memberid}


    AND memodate = #{memodate}

SELECT R1.* FROM( SELECT id, memberid, memodate, vocalevel, (SELECT codename FROM cmm_code WHERE code = vocalevel AND codetype = 'VOCALEVEL') vocalevel_name, vocano, word, `explain` FROM ttokssaemdb.vocamemo
AND memberid = #{memberid}
AND memodate = #{memodate}
ORDER BY vocano ) R1
LIMIT ${length} OFFSET ${start}

mapper.update:
UPDATE ttokssaemdb.checkvocaplan
SET
  examflag = 'B'
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}

UPDATE ttokssaemdb.checkvocaplan
SET
  examflag = #{finishflag}
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}

UPDATE ttokssaemdb.vocaexam
SET
  result = #{finishflag},
  total = ${total},
  wrong = ${wrong},
  findate = now()
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}
  AND degree = #{degree}

UPDATE ttokssaemdb.vocasolve
SET
  answer = #{answer},
  result = #{result}
WHERE
  id = ${id}

mapper.select:
SELECT
  count(*) totcnt
FROM
  ttokssaemdb.vocasolve vocasolve

  AND vocasolve.memberid = #{memberid}
  AND vocasolve.memodate = #{memodate}
  AND vocasolve.degree = ${degree}

SELECT R1.* FROM( SELECT vocasolve.id, vocasolve.memberid, vocasolve.memodate, vocasolve.degree, vocasolve.vocalevel, (SELECT codename FROM cmm_code WHERE code = vocasolve.vocalevel AND codetype = 'VOCALEVEL') vocalevel_name, vocasolve.vocano, vocasolve.word, voca.answer voca_answer, vocasolve.answer, vocasolve.result FROM ttokssaemdb.vocasolve vocasolve, ttokssaemdb.voca voca
AND voca.vocalevel = vocasolve.vocalevel AND voca.vocano = vocasolve.vocano AND vocasolve.memberid = #{memberid} AND vocasolve.memodate = #{memodate} AND vocasolve.degree = ${degree}
ORDER BY vocano ) R1
LIMIT ${length} OFFSET ${start}
